type RegisterHandlersOptions struct {
	// BaseURL is prepended to every registered path so the API can be served
	// under a prefix.
	BaseURL string
	// OperationMiddlewares lets the caller attach per-operation middleware at
	// registration time. The map key is the OpenAPI `operationId` value as it
	// appears in the spec (the raw, un-normalized form). Operations that have
	// no entry are registered with no extra middleware. A nil map disables
	// per-operation middleware entirely.
	OperationMiddlewares map[string][]echo.MiddlewareFunc
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{})
}

// RegisterHandlersWithBaseURL registers handlers and prepends BaseURL to the
// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.GET(options.BaseURL+"/api/swa/livez", wrapper.GetLivez, options.OperationMiddlewares["get-livez"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains", wrapper.GetTrustDomains, options.OperationMiddlewares["get-trust-domains"]...)
	router.POST(options.BaseURL+"/api/swa/trust-domains", wrapper.PostTrustDomain, options.OperationMiddlewares["post-trust-domain"]...)
	router.DELETE(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name", wrapper.DeleteTrustDomain, options.OperationMiddlewares["delete-trust-domain"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name", wrapper.GetTrustDomain, options.OperationMiddlewares["get-trust-domain"]...)
	router.PATCH(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name", wrapper.PatchTrustDomain, options.OperationMiddlewares["patch-trust-domain"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/.well-known/ca-bundles", wrapper.GetCaBundles, options.OperationMiddlewares["get-ca-bundles"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/.well-known/spiffe/bundle.json", wrapper.GetSpiffeBundle, options.OperationMiddlewares["get-spiffe-bundle"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups", wrapper.GetServerGroups, options.OperationMiddlewares["get-server-groups"]...)
	router.POST(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups", wrapper.PostServerGroup, options.OperationMiddlewares["post-server-group"]...)
	router.DELETE(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name", wrapper.DeleteServerGroup, options.OperationMiddlewares["delete-server-group"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name", wrapper.GetServerGroup, options.OperationMiddlewares["get-server-group"]...)
	router.PATCH(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name", wrapper.PatchServerGroup, options.OperationMiddlewares["patch-server-group"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/node-groups", wrapper.GetNodeGroups, options.OperationMiddlewares["get-node-groups"]...)
	router.POST(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/node-groups", wrapper.PostNodeGroups, options.OperationMiddlewares["post-node-groups"]...)
	router.DELETE(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/node-groups/:node-group-name", wrapper.DeleteNodeGroup, options.OperationMiddlewares["delete-node-group"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/node-groups/:node-group-name", wrapper.GetNodeGroup, options.OperationMiddlewares["get-node-group"]...)
	router.PATCH(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/node-groups/:node-group-name", wrapper.PatchNodeGroup, options.OperationMiddlewares["patch-node-group"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/components", wrapper.GetServers, options.OperationMiddlewares["get-servers"]...)
	router.POST(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/components", wrapper.PostServer, options.OperationMiddlewares["post-server"]...)
	router.DELETE(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/components/:server-name", wrapper.DeleteServer, options.OperationMiddlewares["delete-server"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/components/:server-name", wrapper.GetServer, options.OperationMiddlewares["get-server"]...)
	router.PATCH(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/server-groups/:server-group-name/components/:server-name", wrapper.PatchServer, options.OperationMiddlewares["patch-server"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/.well-known/openid-configuration", wrapper.GetOpenidConfiguration, options.OperationMiddlewares["get-openid-configuration"]...)
	router.GET(options.BaseURL+"/api/swa/trust-domains/:trust-domain-name/.well-known/jwks", wrapper.GetJwks, options.OperationMiddlewares["get-jwks"]...)

}
